// ── Fetch API: HTTP methods, headers, error handling ─────────
async function apiClient(baseUrl) {
  async function request(method, path, body) {
    const options = {
      method,
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
    };
    if (body !== undefined) options.body = JSON.stringify(body);

    const res = await fetch(`${baseUrl}${path}`, options);

    // fetch() does NOT throw on 4xx/5xx — check res.ok
    if (!res.ok) {
      const errorBody = await res.text().catch(() => '');
      throw new Error(`HTTP ${res.status} ${res.statusText}: ${errorBody}`);
    }
    // 204 No Content has no body to parse
    if (res.status === 204) return null;
    return res.json();
  }

  return {
    get:    (path)        => request('GET',    path),
    post:   (path, body)  => request('POST',   path, body),
    put:    (path, body)  => request('PUT',    path, body),
    patch:  (path, body)  => request('PATCH',  path, body),
    delete: (path)        => request('DELETE', path),
  };
}

// ── WebSocket: bidirectional real-time channel ───────────────
function createWebSocket(url) {
  const ws = new WebSocket(url);

  ws.addEventListener('open', () => {
    console.log('WS connected');
    ws.send(JSON.stringify({ type: 'subscribe', channel: 'prices' }));
  });

  ws.addEventListener('message', (event) => {
    const data = JSON.parse(event.data);
    console.log('Received:', data);
  });

  ws.addEventListener('close', ({ code, reason }) => {
    console.log(`WS closed: ${code} ${reason}`);
    // Implement exponential backoff reconnect here
  });

  ws.addEventListener('error', (err) => console.error('WS error', err));

  return { send: (msg) => ws.send(JSON.stringify(msg)), close: () => ws.close() };
}

